window.kbPageData["views/entry/k-d1070e5e1a906d75"] = {"key":"entry/k-d1070e5e1a906d75","state":{"route":"entry/k-d1070e5e1a906d75"},"node":{"id":"k-d1070e5e1a906d75","mode":"k","title":"关于党的建设的重要思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"2023 年 6 月 28 日至 29 日召开的全国组织工作会议，用“十三个坚持”集中概括了习\n近平总书记关于党的建设的重要思想，即：\n（1）坚持和加强党的全面领导；\n（2）坚持以党的自我革命引领社会革命（相关论述：党的自我革命是“跳出治乱兴衰\n历史周期率的第二个答案）；\n（3）坚持以党的政治建设统…","sources":[{"id":"158e87308e99f225","label":"关于党的建设的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2023 年 6 月 28 日至 29 日召开的全国组织工作会议，用“十三个坚持”集中概括了习\n近平总书记关于党的建设的重要思想，即：\n（1）坚持和加强党的全面领导；\n（2）坚持以党的自我革命引领社会革命（相关论述：党的自我革命是“跳出治乱兴衰\n历史周期率的第二个答案）；\n（3）坚持以党的政治建设统领党的建设各项工作（相关论述：党的政治建设决定党的\n建设方向和效果；党的政治建设是党的根本性建设；把党的政治建设摆在首位）；\n（4）坚持江山就是人民、人民就是江山（相关论述：站稳人民立场、把握人民愿望、\n尊重人民创造、集中人民智慧）；\n（5）坚持思想建党、理论强党（相关论述：思想建设是党的基础性建设）；\n（粉笔敲黑\n板：注意党的根本性建设是政治建设，基础性建设是思想建设）\n（6）坚持严密党的组织体系；\n（7）坚持造就忠诚干净担当的高素质干部队伍（相关论述：坚持把政治标准放在首位，\n做深做实干部政治素质考察，突出把好政治关、廉洁关）；\n（8）坚持聚天下英才而用之；\n（9）坚持持之以恒正风肃纪（相关论述：作风问题本质上是党性问题）；\n（10）坚持一体推进不敢腐、不能腐、不想腐（相关论述：腐败是最彻底的自我革命）；\n（11）坚持完善党和国家监督体系（相关论述：构建党统一指挥、全面覆盖、权威高\n效的监督体系，把党内监督同国家机关监督、民主监督、司法监督、群众监督、舆论监督贯\n通起来）；\n（12）坚持制度治党、依规治党（相关论述：加强党内法规制度建设是全面从严治党\n的长远之策、根本之策）；\n（13）坚持落实全面从严治党政治责任（相关论述：明确党委（党组）全面从严治党\n主体责任，明确各级纪委的监督责任，明确党委（党组）书记第一责任人责任，明确领导班\n子成员的管党治党责任，明确党员、干部的具体责任）。","source":{"doc":"3ccc56f4000d1642c2d1","first":27,"last":28,"page":27,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-d1070e5e1a906d75":[]}};
